query GetAbandonedCheckouts($cursor: String) {
  abandonedCheckouts(first: 50, after: $cursor) {
    edges {
      node {
        id
        createdAt
        updatedAt
        email
        totalPriceSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        lineItems(first: 10) {
          edges {
            node {
              id
              title
              quantity
              variant {
                id
                title
                price
              }
            }
          }
        }
        customer {
          id
          firstName
          lastName
          email
        }
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

